def join_gpxs(xmls: Iterable[AnyStr]) -> str:
    result_dom = None
    result_gpx_node = None

    for xml in xmls:
        dom = mod_minidom.parseString(xml)
        gpx_node = _find_gpx_node(dom)

        if result_dom is None:
            result_dom = dom
            result_gpx_node = gpx_node
        else:
            if gpx_node and result_gpx_node:
                for child_node in list(gpx_node.childNodes):
                    if child_node.nodeName in ('wpt', 'rte', 'trk'):
                        imported_node = result_dom.importNode(child_node, True)
                        result_gpx_node.appendChild(imported_node)

    if result_dom is None:
        return ''

    return result_dom.toxml()

def _find_gpx_node(dom: Any) -> Any:
    for child_node in dom.childNodes:
        if child_node.nodeName == 'gpx':
            return child_node
    return None
